def has_cycle(graph):
    visited = set()
    path = set()
    def dfs(node):
        if node in path: return True
        if node in visited: return False
        visited.add(node)
        path.add(node)
        for neighbor in graph[node]:
            if dfs(neighbor): return True
        path.remove(node)
        return False
    return any(dfs(node) for node in graph)
